#include <openssl/md5.h>
#include <string>

float consistent_hash(const std::string &msg) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5(reinterpret_cast<const unsigned char*>(msg.data()), msg.size(), digest);

    // Sum all bytes of the digest
    uint32_t sum = 0;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sum += digest[i];
    }

    // Normalize to [0, 1] using the maximum possible sum (16 * 255 = 4080)
    return static_cast<float>(sum) / 4080.0f;
}

#include <openssl/md5.h>
#include <string>

float consistent_hash(const std::string &msg) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5(reinterpret_cast<const unsigned char*>(msg.data()), msg.size(), digest);

    // Treat the digest as a big-endian 128-bit number
    uint64_t sum = 0;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sum = (sum << 8) | digest[i];
    }

    // Normalize to [0, 1] using 2^64 as the modulus
    return static_cast<float>(sum) / 18446744073709551615.0f;
}

#include <string>

float consistent_hash(const std::string &msg) {
    // Fallback hash function if OpenSSL MD5 is not available
    uint32_t sum = 0;
    for (char c : msg) {
        sum = sum * 31 + static_cast<unsigned char>(c);
    }

    // Normalize to [0, 1]
    return static_cast<float>(sum) / 4294967295.0f;
}

